export const instruments={
 piano:{name:'Grand piano',file:'0000',gain:.30},rhodes:{name:'Electric piano',file:'0040',gain:.34},celesta:{name:'Celesta',file:'0080',gain:.28},musicbox:{name:'Music box',file:'0100',gain:.22},vibes:{name:'Vibraphone',file:'0110',gain:.32},bells:{name:'Tubular bells',file:'0140',gain:.20},strings:{name:'Warm strings',file:'0480',gain:.13},pad:{name:'Warm pad',file:'0890',gain:.26}
};
export const progressions={daydream:['Cmaj7','Am7','Fmaj7','G'],weightless:['Dmaj7','A','Bm7','Gmaj7'],afterhours:['Am7','Fmaj7','Cmaj7','Em7'],openwater:['Fmaj7','Cmaj7','Em7','Am7']};
export const soundscapes={stillwater:{voices:['piano','vibes','strings','celesta'],reverb:65,delay:35,text:'Soft keys, warm strings, and a little shimmer.'},glasshouse:{voices:['celesta','musicbox','vibes','bells'],reverb:78,delay:45,text:'Delicate glass tones in a wide, luminous space.'},nightgarden:{voices:['rhodes','pad','strings','vibes'],reverb:82,delay:28,text:'Velvety keys and slow, moonlit textures.'}};
const roots={C:0,D:2,E:4,F:5,G:7,A:9,B:11};
export function parseChord(symbol){const m=/^([A-G])([#b]?)(maj7|m7|m|7|sus2|sus4|add9)?$/.exec(symbol.trim());if(!m)throw new Error('Use chords such as C, Dm, G7, Am7, or Fmaj7.');let root=roots[m[1]]+(m[2]==='#'?1:m[2]==='b'?-1:0);root=(root+12)%12;const shape={maj7:[0,4,7,11],m7:[0,3,7,10],m:[0,3,7],7:[0,4,7,10],sus2:[0,2,7],sus4:[0,5,7],add9:[0,4,7,14]}[m[3]]||[0,4,7];return shape.map(n=>48+root+n);}
export function pitchForPosition(chord,x,voice=0){const base=parseChord(chord),notes=[...base,...base.map(n=>n+12)];let pitch=notes[Math.min(notes.length-1,Math.floor(Math.max(0,Math.min(.999,x))*notes.length))];if(voice===2)pitch-=12;return pitch;}
export function noteName(pitch){return ['C','C♯','D','E♭','E','F','F♯','G','A♭','A','B♭','B'][pitch%12]+(Math.floor(pitch/12)-1);}
export class AmbientAudio{
 constructor(){this.ctx=null;this.player=null;this.loaded=new Map();this.playing=false;this.volume=.55;this.reverb=.65;this.delay=.35;this.bpm=56;}
 async initialize(){if(this.ctx){await this.ctx.resume();return;}const AC=window.AudioContext||window.webkitAudioContext;if(!AC)throw new Error('This browser does not support Web Audio.');if(!window.WebAudioFontPlayer)throw new Error('The instrument engine could not load. Reload to retry.');this.ctx=new AC();await this.ctx.resume();const c=this.ctx;this.player=new window.WebAudioFontPlayer();this.bus=c.createGain();this.filter=c.createBiquadFilter();this.filter.type='lowpass';this.filter.frequency.value=6700;this.filter.Q.value=.3;this.bus.connect(this.filter);this.master=c.createGain();this.master.gain.value=0;this.limiter=c.createDynamicsCompressor();this.limiter.threshold.value=-16;this.limiter.knee.value=18;this.limiter.ratio.value=5;this.limiter.attack.value=.005;this.limiter.release.value=.8;this.limiter.connect(this.master);this.master.connect(c.destination);this.dry=c.createGain();this.dry.gain.value=.7;this.filter.connect(this.dry);this.dry.connect(this.limiter);this.verb=c.createConvolver();const length=c.sampleRate*5,ir=c.createBuffer(2,length,c.sampleRate);for(let ch=0;ch<2;ch++){const data=ir.getChannelData(ch);let prev=0;for(let i=0;i<length;i++){prev=prev*.6+(Math.random()*2-1)*.4;data[i]=prev*Math.pow(1-i/length,2.8)*(Math.min(1,i/900));}}this.verb.buffer=ir;this.wet=c.createGain();this.filter.connect(this.verb);this.verb.connect(this.wet);this.wet.connect(this.limiter);this.echo=c.createDelay(3);this.echo.delayTime.value=60/this.bpm*.75;this.feedback=c.createGain();this.feedback.gain.value=.36;this.echoTone=c.createBiquadFilter();this.echoTone.frequency.value=3100;this.echo.connect(this.echoTone);this.echoTone.connect(this.feedback);this.feedback.connect(this.echo);this.echoWet=c.createGain();this.filter.connect(this.echo);this.echo.connect(this.echoWet);this.echoWet.connect(this.limiter);this.echoWet.connect(this.verb);this.update();}
 async load(key){if(this.loaded.has(key))return this.loaded.get(key);const promise=(async()=>{const name=instruments[key];if(!name)throw new Error('Unknown instrument');const variable='_tone_'+name.file+'_FluidR3_GM_sf2_file';if(!window[variable])await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='vendor/'+name.file+'_FluidR3_GM_sf2_file.js';const timeout=setTimeout(()=>{script.remove();reject(new Error('Instrument loading timed out. Try again.'));},20000);script.onload=()=>{clearTimeout(timeout);resolve();};script.onerror=()=>{clearTimeout(timeout);script.remove();reject(new Error('Could not load '+name.name+'. Try again.'));};document.head.append(script);});const preset=window[variable];await Promise.all(preset.zones.map(async zone=>{if(!zone.buffer&&zone.file){const data=Uint8Array.from(atob(zone.file),s=>s.charCodeAt(0));zone.buffer=await this.ctx.decodeAudioData(data.buffer);}}));this.player.adjustPreset(this.ctx,preset);return preset;})();this.loaded.set(key,promise);try{return await promise;}catch(e){this.loaded.delete(key);throw e;}}
 update(){if(!this.ctx||!this.master)return;const now=this.ctx.currentTime;this.master.gain.setTargetAtTime(this.playing?this.volume*.65:0,now,.08);this.wet.gain.setTargetAtTime(this.reverb*.9,now,.12);this.echoWet.gain.setTargetAtTime(this.delay*.7,now,.1);this.echo.delayTime.setTargetAtTime(60/this.bpm*.75,now,.15);}
 setPlaying(on){this.playing=on;if(!on&&this.player)this.player.cancelQueue(this.ctx);this.update();}
 async note(key,pitch){if(!this.playing||!this.ctx)return;const preset=await this.load(key);if(!this.playing)return;const level=instruments[key].gain*(.85+Math.random()*.15);this.player.queueWaveTable(this.ctx,this.bus,preset,this.ctx.currentTime+.008,pitch,key==='strings'||key==='pad'?3.8:2.7,level);}
}
